package com.acme.hrms.common.security;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

import org.springframework.core.convert.converter.Converter;
import org.springframework.security.authentication.AbstractAuthenticationToken;
import org.springframework.security.core.GrantedAuthority;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;
import org.springframework.security.oauth2.server.resource.authentication.JwtGrantedAuthoritiesConverter;

/**
 * Translates a Keycloak access token into a Spring {@link AbstractAuthenticationToken}
 * with the right authorities for our RBAC matrix.
 *
 * <p>Keycloak places realm roles inside {@code realm_access.roles}. Spring
 * Security's default converter only picks up {@code scope}/{@code scp}, so
 * we extend it manually.
 *
 * <p>Authorities produced look like:
 * <ul>
 *   <li>{@code ROLE_HR_ADMIN}      (from realm role {@code HR_ADMIN})</li>
 *   <li>{@code SCOPE_profile}      (from OAuth2 scope, kept for diagnostics)</li>
 * </ul>
 *
 * <p>The principal name is the {@code preferred_username} claim if present,
 * else {@code email}, else {@code sub}.
 */
public final class JwtRoleConverter implements Converter<Jwt, AbstractAuthenticationToken> {

    private static final String CLAIM_REALM_ACCESS = "realm_access";
    private static final String CLAIM_ROLES = "roles";

    private final JwtGrantedAuthoritiesConverter scopeConverter = new JwtGrantedAuthoritiesConverter();

    @Override
    public AbstractAuthenticationToken convert(Jwt jwt) {
        Collection<GrantedAuthority> authorities = new ArrayList<>(scopeConverter.convert(jwt));
        authorities.addAll(extractRealmRoles(jwt));
        String principalName = resolvePrincipalName(jwt);
        return new JwtAuthenticationToken(jwt, authorities, principalName);
    }

    private Set<GrantedAuthority> extractRealmRoles(Jwt jwt) {
        Map<String, Object> realmAccess = jwt.getClaimAsMap(CLAIM_REALM_ACCESS);
        if (realmAccess == null) {
            return Set.of();
        }
        Object rolesObj = realmAccess.get(CLAIM_ROLES);
        if (!(rolesObj instanceof List<?> rawRoles)) {
            return Set.of();
        }
        Set<GrantedAuthority> result = new HashSet<>();
        for (Object role : rawRoles) {
            if (role instanceof String s && !s.isBlank()) {
                result.add(new SimpleGrantedAuthority(Roles.AUTHORITY_PREFIX + s));
            }
        }
        return result;
    }

    private static String resolvePrincipalName(Jwt jwt) {
        String preferred = jwt.getClaimAsString("preferred_username");
        if (preferred != null && !preferred.isBlank()) {
            return preferred;
        }
        String email = jwt.getClaimAsString("email");
        if (email != null && !email.isBlank()) {
            return email;
        }
        return jwt.getSubject();
    }

package com.acme.hrms.me;

import java.util.List;
import java.util.TreeSet;

import org.slf4j.MDC;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import com.acme.hrms.common.audit.AuditAction;
import com.acme.hrms.common.audit.AuditEvent;
import com.acme.hrms.common.audit.AuditService;
import com.acme.hrms.common.security.CurrentUser;
import com.acme.hrms.common.web.RequestIdFilter;

import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.tags.Tag;

/**
 * Identity probe.
 *
 * <p>Used by the SPA right after login to render the current user's name +
 * roles in the navbar without needing to decode the token client-side.
 * Also doubles as a smoke-test endpoint: if {@code /api/me} returns 200
 * with the right roles, auth wiring works.
 *
 * <p>Each successful call writes one {@link AuditAction#LOGIN} row, which
 * is enough to demonstrate the audit pipeline end-to-end without lighting
 * up audit on every request (we'll do that explicitly per feature later).
 */
@RestController
@RequestMapping("/api/me")
@Tag(name = "Me", description = "Current user identity")
public class MeController {

    private final AuditService auditService;

    public MeController(AuditService auditService) {
        this.auditService = auditService;
    }

    @GetMapping
    @Operation(summary = "Return the identity and realm roles of the caller")
    public MeResponse me(@AuthenticationPrincipal Jwt jwt) {
        CurrentUser user = CurrentUser.from(jwt);
        List<String> sortedRoles = List.copyOf(new TreeSet<>(user.roles()));

        auditService.record(
                AuditEvent.of(AuditAction.LOGIN, "session")
                        .withDetail("GET /api/me"));

        return new MeResponse(
                user.subjectUuid(),
                user.username(),
                user.email(),
                sortedRoles,
                MDC.get(RequestIdFilter.MDC_KEY));
    }
}

package com.acme.hrms.common.security;

import java.util.Optional;
import java.util.Set;
import java.util.UUID;

import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;

/**
 * Snapshot of the caller built from the validated JWT.
 *
 * <p>Pass this through to services that need to make authorisation decisions
 * or write {@code created_by} / {@code updated_by} columns. Never read the
 * {@link SecurityContextHolder} from inside services — take a {@code CurrentUser}
 * argument instead, both for testability and to make the contract explicit.
 *
 * <p>The {@code subjectUuid} field is the Keycloak user id, which we mirror
 * into {@code employee.keycloak_user_id} once the employee module lands.
 */
public record CurrentUser(
        UUID subjectUuid,
        String username,
        String email,
        Set<String> roles
) {

    public boolean hasRole(String role) {
        return roles.contains(role);
    }

    public boolean hasAnyRole(String... candidates) {
        for (String r : candidates) {
            if (roles.contains(r)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Resolve the current user from the security context, if any. Returns
     * empty for anonymous / unauthenticated requests.
     */
    public static Optional<CurrentUser> fromSecurityContext() {
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        if (!(auth instanceof JwtAuthenticationToken token)) {
            return Optional.empty();
        }
        return Optional.of(from(token.getToken()));
    }

    public static CurrentUser from(Jwt jwt) {
        UUID subject = parseSubjectAsUuid(jwt.getSubject());
        String username = jwt.getClaimAsString("preferred_username");
        String email = jwt.getClaimAsString("email");
        Set<String> roles = JwtRoleConverter.rolesOf(jwt);
        return new CurrentUser(subject, username, email, roles);
    }

    private static UUID parseSubjectAsUuid(String subject) {
        if (subject == null || subject.isBlank()) {
            return null;
        }
        try {
            return UUID.fromString(subject);
        } catch (IllegalArgumentException ex) {
            // Keycloak issues UUID subjects, but a non-UUID 'sub' (e.g. for a
            // service account or external IdP) shouldn't blow up auth.
            return null;
        }
    }
}

package com.acme.hrms.common.persistence;

import java.util.Optional;
import java.util.UUID;

import org.springframework.data.domain.AuditorAware;
import org.springframework.stereotype.Component;

import com.acme.hrms.common.security.CurrentUser;

/**
 * Provides the actor UUID for {@code @CreatedBy} / {@code @LastModifiedBy}.
 *
 * <p>For requests with a JWT, returns the Keycloak subject UUID from the
 * security context. For unauthenticated paths or background jobs (no
 * security context yet, but coming in later phases) returns
 * {@link Optional#empty()} — the column is nullable on purpose so we can
 * recognise rows written outside an HTTP context.
 */
@Component("auditorAware")
public class SecurityContextAuditorAware implements AuditorAware<UUID> {

    @Override
    public Optional<UUID> getCurrentAuditor() {
        return CurrentUser.fromSecurityContext()
                .map(CurrentUser::subjectUuid)
                .filter(uuid -> uuid != null);
    }
}

